import { Injectable } from '@angular/core';

@Injectable({
    providedIn: 'root',
})
export class LocalStorageService {
    constructor() {
        this.setSellPageViewHeight();
        this.setSupplyPageViewHeight();
        this.setEditInvoiceDialogHeight();
    }

    // default setter for sell page vh
    setSellPageViewHeight(): void {
        if (!localStorage.getItem('sellTableViewHeight')) {
            localStorage.setItem('sellTableViewHeight', '50vh');
        }
    }

    // sell page vh getter
    public getSellPageViewHeight(): any {
        return localStorage.getItem('sellTableViewHeight');
    }

    // edit invoice dialog height
    setEditInvoiceDialogHeight(): void {
        if (!localStorage.getItem('editInvoiceDialogHeight')) {
            localStorage.setItem('editInvoiceDialogHeight', '40vh');
        }
    }

    // get edit invoice dialog height
    public getEditInvoiceDialogHeight(): any {
        return localStorage.getItem('editInvoiceDialogHeight');
    }

    // default setter for supply page vh
    setSupplyPageViewHeight(): void {
        if (!localStorage.getItem('supplyTableViewHeight')) {
            localStorage.setItem('supplyTableViewHeight', '40vh');
        }
    }

    // supply page vh getter
    public getSupplyPageViewHeight(): string {
        return localStorage.getItem('supplyTableViewHeight');
    }
}
